INSERT INTO "questions" VALUES(1,'Differential Equations','Order and Degree','easy','Find the order and degree (respectively) of the differential equation \((y'''''')^2 + (y'''')^3 + y'' = 0\):','\(3, 3\)','\(2, 2\)','\(2, 3\)','\(3, 2\)','D','The highest-order derivative appearing in the equation is \(y''''''\) (order \(3\)). Its exponent/power is \(2\), so the degree is \(2\). Hence, order is \(3\) and degree is \(2\).');
INSERT INTO "questions" VALUES(2,'Differential Equations','Order and Degree','easy','The degree of the differential equation \(y'''' = \sqrt{1 + y''}\) is:','Not defined','\(1\)','\(\frac{1}{2}\)','\(2\)','D','To determine degree, eliminate radical signs on derivatives by squaring both sides: \((y'''')^2 = 1 + y''\). The highest derivative is \(y''''\) and its power is \(2\), so the degree is \(2\).');
INSERT INTO "questions" VALUES(3,'Differential Equations','Order and Degree','medium','The order and degree (respectively) of the differential equation \((y'''')^{3/2} = y''\) are:','\(2, \frac{3}{2}\)','\(2, 2\)','\(3, 2\)','\(2, 3\)','D','Eliminate fractional powers by squaring both sides: \((y'''')^3 = (y'')^2\). The highest derivative is \(y''''\) (order \(2\)) and its highest power is \(3\) (degree \(3\)). Thus, order is \(2\) and degree is \(3\).');
INSERT INTO "questions" VALUES(4,'Differential Equations','Order and Degree','easy','The degree of the differential equation \(\sin(y'''') + y = x\) is:','\(1\)','\(0\)','\(2\)','Not defined','D','Since the derivative \(y''''\) is an argument inside the transcendental function \(\sin\), the differential equation cannot be expressed as a polynomial in derivatives. Therefore, its degree is not defined.');
INSERT INTO "questions" VALUES(5,'Differential Equations','Order and Degree','medium','The degree of the differential equation \(y'''' + e^y = 0\) is:','\(2\)','Not defined','\(1\)','\(0\)','C','Notice that \(e^y\) involves the dependent variable \(y\), not a derivative. The differential equation is a polynomial in the highest derivative \(y''''\), having power \(1\). Hence, the degree is \(1\).');
INSERT INTO "questions" VALUES(6,'Differential Equations','Order and Degree','medium','The order and degree (respectively) of the differential equation \(y = x y'' + \sqrt{1 + (y'')^2}\) are:','\(1, 1\)','\(2, 2\)','\(1, 2\)','\(2, 1\)','C','Isolate the square root: \(y - x y'' = \sqrt{1 + (y'')^2}\). Squaring both sides yields \((y - x y'')^2 = 1 + (y'')^2\). The highest derivative is \(y''\) (order \(1\)) and its highest degree is \(2\).');
INSERT INTO "questions" VALUES(7,'Differential Equations','Order and Degree','hard','The sum of the order and degree of the differential equation \(\left[1 + (y'')^2\right]^{3/4} = y''''\) is:','\(4\)','\(6\)','\(7\)','\(5\)','B','Raise both sides to the power \(4\) to clear the rational exponent: \(\left[1 + (y'')^2\right]^3 = (y'''')^4\). Here, order is \(2\) (from \(y''''\)) and degree is \(4\) (power of \(y''''\)). Their sum is \(2 + 4 = 6\).');
INSERT INTO "questions" VALUES(8,'Differential Equations','Order and Degree','hard','The order of the differential equation whose general solution is \(y = A e^{2x + B}\) (where \(A, B\) are arbitrary constants) is:','\(1\)','\(0\)','\(3\)','\(2\)','A','Rewrite the solution as \(y = (A e^B) e^{2x} = C e^{2x}\), where \(C = A e^B\) represents a single independent arbitrary constant. Since there is only \(1\) independent constant, the order of the corresponding differential equation is \(1\).');
INSERT INTO "questions" VALUES(9,'Differential Equations','Forming Differential Equations','easy','The differential equation of the family of straight lines \(y = C x\) (where \(C\) is an arbitrary constant) is:','\(x y'' + y = 0\)','\(x y'' = y\)','\(y y'' = x\)','\(y'' = x y\)','B','Differentiating \(y = C x\) with respect to \(x\) gives \(y'' = C\). Substituting \(C = \frac{y}{x}\) yields \(y'' = \frac{y}{x} \implies x y'' = y\).');
INSERT INTO "questions" VALUES(10,'Differential Equations','Forming Differential Equations','easy','The differential equation of the family of curves \(y = A x^2\) (where \(A\) is an arbitrary constant) is:','\(x y'' = 2y\)','\(y'' = 2y\)','\(x y'' + 2y = 0\)','\(x y'' = y\)','A','Differentiating \(y = A x^2\) gives \(y'' = 2Ax\). Since \(A = \frac{y}{x^2}\), we have \(y'' = 2\left(\frac{y}{x^2}\right)x = \frac{2y}{x} \implies x y'' = 2y\).');
INSERT INTO "questions" VALUES(11,'Differential Equations','Forming Differential Equations','medium','The differential equation of the family \(y = A e^x + B e^{-x}\) (where \(A, B\) are arbitrary constants) is:','\(y'''' - y'' = 0\)','\(y'''' - y = 0\)','\(y'' = y\)','\(y'''' + y = 0\)','B','Differentiating once gives \(y'' = A e^x - B e^{-x}\). Differentiating again gives \(y'''' = A e^x + B e^{-x} = y\). Therefore, \(y'''' - y = 0\).');
INSERT INTO "questions" VALUES(12,'Differential Equations','Forming Differential Equations','medium','The differential equation of the family of curves \(y = A \cos(2x) + B \sin(2x)\) is:','\(y'''' = 4y''\)','\(y'''' - 4y = 0\)','\(y'''' + 2y = 0\)','\(y'''' + 4y = 0\)','D','Differentiating twice: \(y'' = -2A\sin(2x) + 2B\cos(2x)\) and \(y'''' = -4A\cos(2x) - 4B\sin(2x) = -4y\). Hence, \(y'''' + 4y = 0\).');
INSERT INTO "questions" VALUES(13,'Differential Equations','Forming Differential Equations','easy','The differential equation representing all concentric circles \(x^2 + y^2 = r^2\) (where \(r\) is an arbitrary radius) is:','\(x y'' + y = 0\)','\(x - y y'' = 0\)','\(x + y y'' = 0\)','\(y'' = x y\)','C','Differentiating \(x^2 + y^2 = r^2\) implicitly with respect to \(x\): \(2x + 2y y'' = 0 \implies x + y y'' = 0\).');
INSERT INTO "questions" VALUES(14,'Differential Equations','Forming Differential Equations','medium','The differential equation of the family of parabolas \(y^2 = 4ax\) (where \(a\) is an arbitrary parameter) is:','\(2x y'' = y\)','\(x y'' = 2y\)','\(y'' = 4y\)','\(y y'' = 2x\)','A','Differentiating \(y^2 = 4ax\) gives \(2y y'' = 4a\). Substituting \(4a = 2y y''\) back: \(y^2 = (2y y'')x \implies y = 2x y''\).');
INSERT INTO "questions" VALUES(15,'Differential Equations','Forming Differential Equations','medium','The order and degree (respectively) of the differential equation of the family \(y = A x + A^2\) (where \(A\) is an arbitrary parameter) are:','\(1, 1\)','\(2, 2\)','\(2, 1\)','\(1, 2\)','D','Differentiating gives \(y'' = A\). Substituting \(A = y''\) into the original equation yields \(y = x y'' + (y'')^2\). This is an equation of order \(1\) and degree \(2\).');
INSERT INTO "questions" VALUES(16,'Differential Equations','Forming Differential Equations','hard','The differential equation of all parabolas whose axis coincides with the \(x\)-axis is:','\(y y'''' + (y'')^2 = 0\)','\(y y'''' - (y'')^2 = 0\)','\(y'''' + y = 0\)','\(y'' y'''' = 0\)','A','Parabolas with the \(x\)-axis as their axis have equation \(y^2 = 4a(x - h)\) with two arbitrary constants \(a\) and \(h\). Differentiating once gives \(2y y'' = 4a \implies y y'' = 2a\). Differentiating again gives \(y y'''' + (y'')^2 = 0\).');
INSERT INTO "questions" VALUES(17,'Differential Equations','Variable Separable','easy','The general solution of the differential equation \(\frac{dy}{dx} = \frac{x}{y}\) is:','\(y^2 = x^2 + C\)','\(y^2 = 2x + C\)','\(y = \ln|x| + C\)','\(y = \frac{x^2}{2} + C\)','A','Separating variables: \(y\,dy = x\,dx\). Integrating both sides gives \(\int y\,dy = \int x\,dx \implies \frac{y^2}{2} = \frac{x^2}{2} + c \implies y^2 = x^2 + C\).');
INSERT INTO "questions" VALUES(18,'Differential Equations','Variable Separable','medium','The general solution of \(\frac{dy}{dx} = e^{x - y}\) is:','\(y = e^x + C\)','\(e^y = e^{-x} + C\)','\(e^y = e^x + C\)','\(e^{-y} = e^{-x} + C\)','C','Express \(e^{x-y} = e^x e^{-y}\). Separating variables gives \(e^y\,dy = e^x\,dx\). Integrating both sides: \(\int e^y\,dy = \int e^x\,dx \implies e^y = e^x + C\).');
INSERT INTO "questions" VALUES(19,'Differential Equations','Variable Separable','medium','The solution of the differential equation \(\frac{dy}{dx} = \frac{1 + y^2}{1 + x^2}\) is:','\(y = \tan^{-1}(x) + C\)','\(y = \tan(x) + C\)','\(\tan^{-1}(y) - \tan^{-1}(x) = C\)','\(\tan^{-1}(y) + \tan^{-1}(x) = C\)','C','Separating variables gives \(\frac{dy}{1 + y^2} = \frac{dx}{1 + x^2}\). Integrating both sides: \(\int \frac{dy}{1 + y^2} = \int \frac{dx}{1 + x^2} \implies \tan^{-1}(y) = \tan^{-1}(x) + C \implies \tan^{-1}(y) - \tan^{-1}(x) = C\).');
INSERT INTO "questions" VALUES(20,'Differential Equations','Variable Separable','medium','The solution of \((1 + x^2)\frac{dy}{dx} + 1 + y^2 = 0\) is:','\(\tan^{-1}(x) + \tan^{-1}(y) = C\)','\(\tan^{-1}(xy) = C\)','\(x + y = C\)','\(\tan^{-1}(x) - \tan^{-1}(y) = C\)','A','Rearranging gives \(\frac{dy}{1 + y^2} = -\frac{dx}{1 + x^2}\). Integrating both sides gives \(\tan^{-1}(y) = -\tan^{-1}(x) + C \implies \tan^{-1}(x) + \tan^{-1}(y) = C\).');
INSERT INTO "questions" VALUES(21,'Differential Equations','Variable Separable','easy','The particular solution of \(\frac{dy}{dx} = 3y\) with \(y(0) = 2\) is:','\(y = 2e^{3x}\)','\(y = 3e^{2x}\)','\(y = e^{3x} + 1\)','\(y = 2 + 3x\)','A','Separating variables gives \(\frac{dy}{y} = 3\,dx\). Integrating: \(\ln|y| = 3x + c \implies y = A e^{3x}\). Applying \(y(0) = 2 \implies 2 = A e^0 = A\). Hence, \(y = 2e^{3x}\).');
INSERT INTO "questions" VALUES(22,'Differential Equations','Variable Separable','easy','The solution of the differential equation \(x\,dy - y\,dx = 0\) is:','\(y = Cx\)','\(x^2 + y^2 = C\)','\(xy = C\)','\(y = C + x\)','A','Separating variables: \(\frac{dy}{y} = \frac{dx}{x}\). Integrating: \(\ln|y| = \ln|x| + \ln C \implies \ln|y| = \ln|Cx| \implies y = Cx\).');
INSERT INTO "questions" VALUES(23,'Differential Equations','Variable Separable','medium','The general solution of \(\frac{dy}{dx} + y = 2\) is:','\(y = 2 + C e^{-x}\)','\(y = 2 + C e^x\)','\(y = 2x + C\)','\(y = 2 - x + C\)','A','Rearranging gives \(\frac{dy}{2 - y} = dx\). Integrating: \(-\ln|2 - y| = x + c \implies \ln|2 - y| = -x - c \implies 2 - y = K e^{-x} \implies y = 2 + C e^{-x}\).');
INSERT INTO "questions" VALUES(24,'Differential Equations','Variable Separable','medium','The equation of the curve passing through \((1, 3)\) which satisfies \(\frac{dy}{dx} = 2x - \frac{1}{x^2}\) is:','\(y = x^2 + \frac{1}{x} + 3\)','\(y = x^2 - \frac{1}{x} + 1\)','\(y = x^2 + \frac{1}{x} + 1\)','\(y = x^2 - \frac{1}{x} + 3\)','C','Integrating: \(y = \int \left(2x - x^{-2}\right)dx = x^2 + \frac{1}{x} + C\). Given the curve passes through \((1, 3)\): \(3 = 1^2 + \frac{1}{1} + C \implies 3 = 2 + C \implies C = 1\). Hence, \(y = x^2 + \frac{1}{x} + 1\).');
INSERT INTO "questions" VALUES(25,'Differential Equations','Variable Separable','medium','The solution of \(\frac{dy}{dx} = \frac{2y}{x}\) passing through the point \((1, 4)\) is:','\(y = x^4\)','\(y = 2x^2\)','\(y = 4x\)','\(y = 4x^2\)','D','Separating variables: \(\frac{dy}{y} = \frac{2\,dx}{x}\). Integrating: \(\ln|y| = 2\ln|x| + \ln C = \ln(Cx^2) \implies y = Cx^2\). Using \((x, y) = (1, 4)\): \(4 = C(1)^2 \implies C = 4\). Thus, \(y = 4x^2\).');
INSERT INTO "questions" VALUES(26,'Differential Equations','Linear DE and Integrating Factor','easy','The integrating factor (I.F.) of \(\frac{dy}{dx} + y\tan(x) = \sec(x)\) is:','\(e^{\sec(x)}\)','\(\tan(x)\)','\(\cos(x)\)','\(\sec(x)\)','D','Comparing with \(\frac{dy}{dx} + Py = Q\), we have \(P = \tan(x)\). Then \(\text{I.F.} = e^{\int P\,dx} = e^{\int \tan(x)\,dx} = e^{\ln|\sec(x)|} = \sec(x)\).');
INSERT INTO "questions" VALUES(27,'Differential Equations','Linear DE and Integrating Factor','medium','The integrating factor of \((x\ln x)\frac{dy}{dx} + y = 2\ln x\) is:','\(e^x\)','\(\ln(\ln x)\)','\(x\)','\(\ln(x)\)','D','Dividing by \(x\ln x\): \(\frac{dy}{dx} + \frac{1}{x\ln x}y = \frac{2}{x}\). Here \(P = \frac{1}{x\ln x}\). Then \(\int P\,dx = \int \frac{dx}{x\ln x} = \ln(\ln x)\). Hence, \(\text{I.F.} = e^{\ln(\ln x)} = \ln(x)\).');
INSERT INTO "questions" VALUES(28,'Differential Equations','Linear DE and Integrating Factor','medium','The integrating factor of \(x\frac{dy}{dx} + 3y = x^4\) is:','\(x^4\)','\(3\ln(x)\)','\(x^3\)','\(e^{3x}\)','C','Putting into standard form: \(\frac{dy}{dx} + \frac{3}{x}y = x^3\). Thus \(P = \frac{3}{x}\). Then \(\text{I.F.} = e^{\int \frac{3}{x}dx} = e^{3\ln x} = e^{\ln(x^3)} = x^3\).');
INSERT INTO "questions" VALUES(29,'Differential Equations','Linear DE and Integrating Factor','medium','If the integrating factor of the linear differential equation \(\frac{dy}{dx} + P(x)y = Q(x)\) is \(\sin(x)\), then \(P(x)\) is:','\(\cos(x)\)','\(\cot(x)\)','\(\tan(x)\)','\(-\cot(x)\)','B','Given \(\text{I.F.} = e^{\int P\,dx} = \sin(x)\). Taking natural logarithm: \(\int P\,dx = \ln(\sin x)\). Differentiating with respect to \(x\): \(P = \frac{d}{dx}[\ln(\sin x)] = \frac{\cos x}{\sin x} = \cot(x)\).');
INSERT INTO "questions" VALUES(30,'Differential Equations','Linear DE and Integrating Factor','hard','The integrating factor of \((1 + x^2)\frac{dy}{dx} + xy = 1\) is:','\(\sqrt{1 + x^2}\)','\(\frac{1}{\sqrt{1 + x^2}}\)','\(1 + x^2\)','\(\ln(1 + x^2)\)','A','Standard form: \(\frac{dy}{dx} + \frac{x}{1 + x^2}y = \frac{1}{1 + x^2}\). Thus \(P = \frac{x}{1 + x^2}\). Then \(\int P\,dx = \frac{1}{2}\int \frac{2x}{1 + x^2}dx = \frac{1}{2}\ln(1 + x^2) = \ln\sqrt{1 + x^2}\). Hence, \(\text{I.F.} = e^{\ln\sqrt{1 + x^2}} = \sqrt{1 + x^2}\).');
INSERT INTO "questions" VALUES(31,'Differential Equations','Linear DE and Integrating Factor','medium','The general solution of \(\frac{dy}{dx} + y\tan(x) = \sec(x)\) is:','\(y = \sin(x) + C\cos(x)\)','\(y = \tan(x) + C\)','\(y\sec(x) = \sec(x)\tan(x) + C\)','\(y = \cos(x) + C\sin(x)\)','A','\(\text{I.F.} = \sec(x)\). The general solution is \(y \cdot \sec(x) = \int \sec(x)\sec(x)\,dx + C = \int \sec^2(x)\,dx + C = \tan(x) + C\). Dividing by \(\sec(x)\) (multiplying by \(\cos(x)\)): \(y = \tan(x)\cos(x) + C\cos(x) = \sin(x) + C\cos(x)\).');
INSERT INTO "questions" VALUES(32,'Differential Equations','Linear DE and Integrating Factor','medium','The general solution of \(x\frac{dy}{dx} + 2y = x^2\) is:','\(y = \frac{x^3}{4} + \frac{C}{x^2}\)','\(y = \frac{x^2}{2} + \frac{C}{x^2}\)','\(y = \frac{x^2}{4} + Cx^2\)','\(y = \frac{x^2}{4} + \frac{C}{x^2}\)','D','Standard form: \(\frac{dy}{dx} + \frac{2}{x}y = x\). \(\text{I.F.} = e^{\int \frac{2}{x}dx} = x^2\). The solution is \(y \cdot x^2 = \int x \cdot x^2\,dx + C = \int x^3\,dx + C = \frac{x^4}{4} + C\). Dividing by \(x^2\): \(y = \frac{x^2}{4} + \frac{C}{x^2}\).');
INSERT INTO "questions" VALUES(33,'Differential Equations','Linear DE and Integrating Factor','medium','The general solution of \(\frac{dy}{dx} + y = e^{-x}\) is:','\(y = (x + C)e^x\)','\(y = xe^{-x} + C\)','\(y = (x + C)e^{-x}\)','\(y = e^{-x} + Cx\)','C','Standard linear form with \(P = 1\), \(\text{I.F.} = e^{\int 1\,dx} = e^x\). The solution is \(y \cdot e^x = \int e^{-x} \cdot e^x\,dx + C = \int 1\,dx + C = x + C\). Multiplying by \(e^{-x}\): \(y = (x + C)e^{-x}\).');
INSERT INTO "questions" VALUES(34,'Differential Equations','Linear DE and Integrating Factor','medium','The general solution of \(\frac{dy}{dx} - y = e^x\) is:','\(y = xe^x + Ce^{-x}\)','\(y = e^x + C\)','\(y = (x + C)e^{-x}\)','\(y = (x + C)e^x\)','D','Here \(P = -1\), so \(\text{I.F.} = e^{\int -1\,dx} = e^{-x}\). The solution is \(y \cdot e^{-x} = \int e^x \cdot e^{-x}\,dx + C = \int 1\,dx + C = x + C\). Multiplying by \(e^x\): \(y = (x + C)e^x\).');
INSERT INTO "questions" VALUES(35,'Differential Equations','Homogeneous DE','easy','Which of the following differential equations is homogeneous?','\(\frac{dy}{dx} = \frac{x^2 + y}{x}\)','\(\frac{dy}{dx} = \frac{xy}{x + 1}\)','\(\frac{dy}{dx} = \frac{x^2 + y^2}{xy}\)','\(\frac{dy}{dx} = \frac{x + y + 1}{x}\)','C','An equation \(\frac{dy}{dx} = \frac{f(x,y)}{g(x,y)}\) is homogeneous if all terms in \(f(x,y)\) and \(g(x,y)\) have the same degree. In C, numerator \(x^2 + y^2\) has degree \(2\) and denominator \(xy\) has degree \(1+1=2\). Hence, \(\frac{x^2 + y^2}{xy}\) is a homogeneous function of degree \(0\).');
INSERT INTO "questions" VALUES(36,'Differential Equations','Homogeneous DE','easy','Under the homogeneous substitution \(y = vx\), the derivative \(\frac{dy}{dx}\) transforms into:','\(\frac{dv}{dx}\)','\(x\frac{dv}{dx}\)','\(v\frac{dv}{dx}\)','\(v + x\frac{dv}{dx}\)','D','With \(y = v \cdot x\) (where \(v = v(x)\)), differentiating with respect to \(x\) using the product rule: \(\frac{dy}{dx} = v\frac{d}{dx}(x) + x\frac{dv}{dx} = v + x\frac{dv}{dx}\).');
INSERT INTO "questions" VALUES(37,'Differential Equations','Homogeneous DE','medium','The general solution of the differential equation \(\frac{dy}{dx} = \frac{x + y}{x}\) is:','\(y = x\ln|x| + C\)','\(y = x(\ln|x| + C)\)','\(y = x^2(\ln|x| + C)\)','\(y = \ln|x| + C\)','B','Rewriting: \(\frac{dy}{dx} = 1 + \frac{y}{x}\). Substitute \(y = vx \implies \frac{dy}{dx} = v + x\frac{dv}{dx}\). Then \(v + x\frac{dv}{dx} = 1 + v \implies x\frac{dv}{dx} = 1 \implies dv = \frac{dx}{x}\). Integrating: \(v = \ln|x| + C\). Substituting \(v = \frac{y}{x}\): \(y = x(\ln|x| + C)\).');
INSERT INTO "questions" VALUES(38,'Differential Equations','Homogeneous DE','hard','The solution of \(\frac{dy}{dx} = \frac{y}{x} + \tan\left(\frac{y}{x}\right)\) is:','\(\sin\left(\frac{y}{x}\right) = Cy\)','\(\tan\left(\frac{y}{x}\right) = Cx\)','\(\cos\left(\frac{y}{x}\right) = Cx\)','\(\sin\left(\frac{y}{x}\right) = Cx\)','D','Putting \(y = vx \implies \frac{dy}{dx} = v + x\frac{dv}{dx}\). Then \(v + x\frac{dv}{dx} = v + \tan(v) \implies x\frac{dv}{dx} = \tan(v) \implies \cot(v)\,dv = \frac{dx}{x}\). Integrating: \(\ln|\sin(v)| = \ln|x| + \ln C = \ln|Cx| \implies \sin(v) = Cx \implies \sin\left(\frac{y}{x}\right) = Cx\).');
INSERT INTO "questions" VALUES(39,'Differential Equations','Homogeneous DE','hard','The solution of \(\frac{dy}{dx} = \frac{y}{x} + 2\tan\left(\frac{y}{x}\right)\) is:','\(\sin\left(\frac{y}{x}\right) = Cx\)','\(\sin\left(\frac{y}{x}\right) = Cx^2\)','\(\cos\left(\frac{y}{x}\right) = Cx^2\)','\(\sin\left(\frac{y}{x}\right) = \frac{C}{x^2}\)','B','Putting \(y = vx \implies v + x\frac{dv}{dx} = v + 2\tan(v) \implies x\frac{dv}{dx} = 2\tan(v) \implies \cot(v)\,dv = \frac{2\,dx}{x}\). Integrating: \(\ln|\sin(v)| = 2\ln|x| + \ln C = \ln(Cx^2) \implies \sin(v) = Cx^2 \implies \sin\left(\frac{y}{x}\right) = Cx^2\).');
INSERT INTO "questions" VALUES(40,'Differential Equations','Homogeneous DE','medium','The general solution of \(\frac{dy}{dx} = \frac{2y - x}{x}\) is:','\(y - x = Cx^2\)','\(y + x = Cx^2\)','\(y - x = Cx\)','\(y - x = C\)','A','Rewriting: \(\frac{dy}{dx} = 2\left(\frac{y}{x}\right) - 1\). Putting \(y = vx \implies v + x\frac{dv}{dx} = 2v - 1 \implies x\frac{dv}{dx} = v - 1 \implies \frac{dv}{v - 1} = \frac{dx}{x}\). Integrating: \(\ln|v - 1| = \ln|x| + \ln C \implies v - 1 = Cx\). Since \(v = \frac{y}{x}\): \(\frac{y}{x} - 1 = Cx \implies y - x = Cx^2\).');
INSERT INTO "questions" VALUES(41,'Differential Equations','Homogeneous DE','hard','The general solution of \(\frac{dy}{dx} = \frac{y}{x} + \frac{y^2}{x^2}\) is:','\(-\frac{y}{x} = \ln|x| + C\)','\(\frac{y}{x} = \ln|x| + C\)','\(\frac{x}{y} = \ln|x| + C\)','\(-\frac{x}{y} = \ln|x| + C\)','D','Putting \(y = vx \implies v + x\frac{dv}{dx} = v + v^2 \implies x\frac{dv}{dx} = v^2 \implies \frac{dv}{v^2} = \frac{dx}{x}\). Integrating: \(-\frac{1}{v} = \ln|x| + C\). Substituting \(v = \frac{y}{x}\) gives \(-\frac{x}{y} = \ln|x| + C\).');
INSERT INTO "questions" VALUES(42,'Differential Equations','Perfect Differentials','easy','The general solution of the exact differential equation \(x\,dy + y\,dx = 0\) is:','\(x + y = C\)','\(xy = C\)','\(y = Cx\)','\(x^2 + y^2 = C\)','B','Notice that \(x\,dy + y\,dx = d(xy) = 0\). Integrating directly: \(\int d(xy) = \int 0 \implies xy = C\).');
INSERT INTO "questions" VALUES(43,'Differential Equations','Perfect Differentials','medium','The general solution of \(x\,dy - y\,dx = x^2\,dx\) is:','\(y = x^2 + C\)','\(\frac{y}{x} = x + C\)','\(\frac{x}{y} = x + C\)','\(y = x + C\)','B','Dividing through by \(x^2\): \(\frac{x\,dy - y\,dx}{x^2} = dx\). The left hand side is the quotient rule differential \(d\left(\frac{y}{x}\right)\). Integrating: \(\int d\left(\frac{y}{x}\right) = \int dx \implies \frac{y}{x} = x + C\).');
INSERT INTO "questions" VALUES(44,'Differential Equations','Perfect Differentials','easy','The general solution of \(x\,dx + y\,dy = 0\) is:','\(x^2 - y^2 = C\)','\(x + y = C\)','\(xy = C\)','\(x^2 + y^2 = C\)','D','Integrating both sides directly: \(\int x\,dx + \int y\,dy = c \implies \frac{x^2}{2} + \frac{y^2}{2} = c \implies x^2 + y^2 = C\).');
INSERT INTO "questions" VALUES(45,'Differential Equations','Perfect Differentials','medium','The general solution of \(x^3\,dy + y^3\,dx = 0\) is:','\(x^2 + y^2 = C\)','\(\frac{1}{x^2} + \frac{1}{y^2} = C\)','\(\frac{1}{x} + \frac{1}{y} = C\)','\(\frac{1}{x^3} + \frac{1}{y^3} = C\)','B','Dividing through by \(x^3 y^3\): \(\frac{dy}{y^3} + \frac{dx}{x^3} = 0 \implies y^{-3}\,dy + x^{-3}\,dx = 0\). Integrating: \(\frac{y^{-2}}{-2} + \frac{x^{-2}}{-2} = c \implies -\frac{1}{2y^2} - \frac{1}{2x^2} = c \implies \frac{1}{x^2} + \frac{1}{y^2} = C\).');
INSERT INTO "questions" VALUES(46,'Differential Equations','Basics and Applications','easy','Which of the following functions is a solution of \(y'''' + y = 0\)?','\(y = \sin(x)\)','\(y = e^x\)','\(y = x^2\)','\(y = \sin(2x)\)','A','If \(y = \sin(x)\), then \(y'' = \cos(x)\) and \(y'''' = -\sin(x)\). Substituting: \(y'''' + y = -\sin(x) + \sin(x) = 0\), satisfying the equation. For \(y = \sin(2x)\), \(y'''' = -4\sin(2x)\), so \(y'''' + y = -3\sin(2x) \neq 0\).');
INSERT INTO "questions" VALUES(47,'Differential Equations','Basics and Applications','easy','The particular solution of \(\frac{dy}{dx} = e^x\) satisfying the initial condition \(y(0) = 2\) is:','\(y = e^x\)','\(y = e^x + 1\)','\(y = 2e^x\)','\(y = e^x + 2\)','B','Integrating gives \(y = e^x + C\). Using the initial condition \(y(0) = 2\): \(2 = e^0 + C = 1 + C \implies C = 1\). Hence, the particular solution is \(y = e^x + 1\).');
INSERT INTO "questions" VALUES(48,'Differential Equations','Basics and Applications','medium','The number of arbitrary constants in a particular solution of a differential equation of order \(n\) is:','\(0\)','\(n - 1\)','\(n\)','\(1\)','A','A particular solution is derived from the general solution by specifying all arbitrary constants through given initial or boundary conditions. Hence, it contains zero (\(0\)) arbitrary constants. (Note: A general solution of order \(n\) contains \(n\) arbitrary constants).');
INSERT INTO "questions" VALUES(49,'Differential Equations','Basics and Applications','medium','The rate of growth of a population is proportional to the population present: \(\frac{dN}{dt} = kN\). If the population doubles in \(10\) years, after \(20\) years it becomes how many times the original?','\(2\)','\(3\)','\(4\)','\(6\)','C','The solution is \(N(t) = N_0 e^{kt}\). Given it doubles in \(10\) years: \(2N_0 = N_0 e^{10k} \implies e^{10k} = 2\). At \(t = 20\) years: \(N(20) = N_0 e^{20k} = N_0 (e^{10k})^2 = N_0 (2)^2 = 4N_0\). Thus, it becomes \(4\) times the original population.');
INSERT INTO "questions" VALUES(50,'Differential Equations','Basics and Applications','hard','The order of the differential equation representing all circles of fixed radius \(r = 5\) with arbitrary centre \((h, k)\) is:','\(4\)','\(1\)','\(2\)','\(3\)','C','The equation of such circles is \((x - h)^2 + (y - k)^2 = 5^2 = 25\). The parameters \(h\) and \(k\) are the only two essential arbitrary constants. Therefore, the order of the differential equation is \(2\).');
